begin;
create table public.professional_proposals(id uuid primary key default gen_random_uuid(),mission_id uuid not null,artifact_version_id uuid not null unique,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,artifact_version_id)references public.artifact_versions(mission_id,id));
create table public.professional_engagements(
 id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),professional_id uuid not null references public.counterparties(id),decision_id uuid not null,artifact_version_id uuid not null,brief_version_id uuid not null,quote_evidence_id uuid not null,verification_evidence_ids uuid[] not null,email text not null,mandate_id uuid,task_id uuid not null default gen_random_uuid(),request_key text not null,request_hash text not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,id),unique(mission_id,request_key),unique(artifact_version_id),unique(task_id),
 unique(quote_evidence_id),foreign key(mission_id,decision_id)references public.decisions(mission_id,id),foreign key(mission_id,artifact_version_id)references public.artifact_versions(mission_id,id),foreign key(mission_id,brief_version_id)references public.artifact_versions(mission_id,id),foreign key(mission_id,quote_evidence_id)references public.evidence(mission_id,id),foreign key(mission_id,mandate_id)references public.mandates(mission_id,id));
create table public.professional_starts(id uuid primary key default gen_random_uuid(),mission_id uuid not null,engagement_id uuid not null unique,receipt_id uuid not null unique,commitment_id uuid not null,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,engagement_id)references public.professional_engagements(mission_id,id),foreign key(mission_id,receipt_id)references public.provider_receipts(mission_id,id),foreign key(mission_id,commitment_id)references public.commitments(mission_id,id));
create table public.professional_deliveries(id uuid primary key default gen_random_uuid(),mission_id uuid not null,engagement_id uuid not null,deliverable_id text not null,source_evidence_id uuid not null,document_version_id uuid not null,claimed_evidence_id uuid not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,id),unique(engagement_id,deliverable_id,source_evidence_id,document_version_id),foreign key(mission_id,engagement_id)references public.professional_engagements(mission_id,id),foreign key(mission_id,source_evidence_id)references public.evidence(mission_id,id),foreign key(mission_id,document_version_id)references public.artifact_versions(mission_id,id),foreign key(mission_id,claimed_evidence_id)references public.evidence(mission_id,id));
create table public.professional_confirmations(id uuid primary key default gen_random_uuid(),mission_id uuid not null,delivery_id uuid not null,decision_id uuid not null,evidence_id uuid not null,created_at timestamptz not null default clock_timestamp(),unique(delivery_id,decision_id),foreign key(mission_id,delivery_id)references public.professional_deliveries(mission_id,id),foreign key(mission_id,decision_id)references public.decisions(mission_id,id),foreign key(mission_id,evidence_id)references public.evidence(mission_id,id));
create table public.professional_payments(id uuid primary key default gen_random_uuid(),mission_id uuid not null,engagement_id uuid not null,payment_id uuid not null unique,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,engagement_id)references public.professional_engagements(mission_id,id),foreign key(mission_id,payment_id)references public.payments(mission_id,id));
create table public.professional_holds(id uuid primary key default gen_random_uuid(),mission_id uuid not null,engagement_id uuid not null,status text not null check(status in('draft','blocked','ambiguous')),reason text not null check(length(reason)between 1 and 500),created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,engagement_id)references public.professional_engagements(mission_id,id));
do $$declare t text;begin foreach t in array array['professional_proposals','professional_engagements','professional_starts','professional_deliveries','professional_confirmations','professional_payments','professional_holds']loop
 execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy mission_scope on public.%I using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id))',t);
 execute format('create trigger immutable_row before update or delete on public.%I for each row execute function private.immutable_row()',t);execute format('create trigger ledger_revision after insert on public.%I for each row execute function private.record_ledger_revision()',t);execute format('create trigger broadcast_ledger after insert on public.%I for each row execute function private.broadcast_ledger()',t);execute format('grant select on public.%I to founder_role,lead_role,specialist_role,policy_role',t);
end loop;end$$;

create function private.professional_evidence_current(p_mission uuid,p_id uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select from public.evidence e where e.mission_id=p_mission and e.id=p_id and not exists(select from public.stale_marks s where s.mission_id=p_mission and s.node_id=e.id)and not exists(select from public.evidence n where n.mission_id=p_mission and n.supersedes_id=e.id))$$;
create function private.professional_verified(p_mission uuid,p_professional uuid,p_email text,p_refs uuid[],p_regulated boolean)returns boolean language sql stable security definer set search_path=''as $$
 select exists(select from public.counterparties c join public.missions m on m.founder_id=c.founder_id where m.id=p_mission and c.id=p_professional and c.kind='specialist'and not c.opt_out and c.channels->>'email'=p_email and c.verification->>'emailVerified'='true'and not exists(select from public.counterparty_optouts o where o.counterparty_id=c.id))
 and cardinality(p_refs)>=2 and not exists(select from unnest(p_refs)ref where not exists(select from public.evidence e where e.mission_id=p_mission and e.id=ref and e.payload->>'professionalId'=p_professional::text and e.trust in('verified','founder_confirmed')and length(trim(coalesce(e.payload->>'independentSource','')))>0 and private.professional_evidence_current(p_mission,e.id)))
 and(select count(distinct e.payload->>'independentSource')from public.evidence e where e.mission_id=p_mission and e.id=any(p_refs))>=2
 and exists(select from public.evidence e where e.mission_id=p_mission and e.id=any(p_refs)and e.payload->>'signalKind'in('registry','marketplace_history'))
 and(not p_regulated or exists(select from public.evidence e where e.mission_id=p_mission and e.id=any(p_refs)and e.payload->>'signalKind'='qualification'and length(trim(coalesce(e.payload->>'licenceReference','')))>0 and private.readiness_date(e.payload->>'validUntil')>clock_timestamp()))
$$;
create function private.professional_source(p_mission uuid,p_version uuid,p_start boolean default false)returns jsonb language plpgsql stable security definer set search_path=''as $$declare terms jsonb;quote jsonb;email text;refs uuid[];begin
 select content->'professionalEngagement'into terms from public.artifact_versions where mission_id=p_mission and id=p_version;
 if terms is null or not exists(select from public.professional_proposals where mission_id=p_mission and artifact_version_id=p_version)or not private.readiness_current_approved(p_mission,p_version)or not private.readiness_current_approved(p_mission,(terms->>'briefVersionId')::uuid)then raise exception 'needs_approval: current approved prepared professional engagement and brief required';end if;
 select channels->>'email'into email from public.counterparties where id=(terms->>'professionalId')::uuid;
 select array_agg(id::uuid)into refs from jsonb_array_elements_text(terms->'verificationEvidenceIds')id;
 if not private.professional_verified(p_mission,(terms->>'professionalId')::uuid,email,refs,(terms->>'regulated')::boolean)then raise exception 'needs_approval: current professional verification, qualification and consent required';end if;
 select evidence.payload into quote from public.evidence evidence where mission_id=p_mission and id=(terms->>'quoteEvidenceId')::uuid and source_type in('document','message','url')and private.professional_evidence_current(p_mission,id);
 if quote is null or quote->>'professionalId'is distinct from terms->>'professionalId'or quote->>'briefVersionId'is distinct from terms->>'briefVersionId'or quote->'amountMinor'is distinct from terms->'amountMinor'or quote->>'currency'is distinct from terms->>'currency'or(p_start and not coalesce(private.readiness_date(quote->>'validUntil')>clock_timestamp(),false))then raise exception 'needs_approval: exact current professional quote required';end if;
 return terms;
end$$;

create function public.prepare_professional_engagement(p_mission uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare brief jsonb;quote jsonb;ref text;item jsonb;payload jsonb;body text;art uuid;version uuid;begin
 perform private.require_role(array['specialist_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);perform private.assert_safe_content(p_input);
 if coalesce(p_input->>'language','en')not in('en','ar')or jsonb_typeof(p_input)is distinct from'object'or not(p_input?&array['professionalId','briefVersionId','quoteEvidenceId','verificationEvidenceIds','amountMinor','currency','dueAt','service','regulated','deliverables'])or(p_input->>'amountMinor')!~'^[1-9][0-9]*$'or(p_input->>'amountMinor')::numeric>9007199254740991 or(p_input->>'currency')!~'^[A-Z]{3}$'or jsonb_typeof(p_input->'regulated')is distinct from'boolean'or length(trim(coalesce(p_input->>'service','')))not between 1 and 200 or not coalesce(private.readiness_date(p_input->>'dueAt')>clock_timestamp(),false)or jsonb_typeof(p_input->'deliverables')is distinct from'array'or jsonb_array_length(p_input->'deliverables')not between 1 and 20 or jsonb_typeof(p_input->'verificationEvidenceIds')is distinct from'array'then raise exception 'validation: complete bounded professional terms required';end if;
 if not private.readiness_current_approved(p_mission,(p_input->>'briefVersionId')::uuid)then raise exception 'needs_approval: current approved professional brief required';end if;
 select content into strict brief from public.artifact_versions where mission_id=p_mission and id=(p_input->>'briefVersionId')::uuid;
 select evidence.payload into quote from public.evidence evidence where mission_id=p_mission and id=(p_input->>'quoteEvidenceId')::uuid and source_type in('document','message','url')and private.professional_evidence_current(p_mission,id);
 if quote is null or jsonb_typeof(quote->'deliverableIds')is distinct from'array'or quote->>'professionalId'is distinct from p_input->>'professionalId'or quote->>'briefVersionId'is distinct from p_input->>'briefVersionId'or quote->'amountMinor'is distinct from p_input->'amountMinor'or quote->>'currency'is distinct from p_input->>'currency'or not coalesce(private.readiness_date(quote->>'validUntil')>clock_timestamp(),false)then raise exception 'validation: exact unexpired returned professional quote required';end if;
 if not private.professional_verified(p_mission,(p_input->>'professionalId')::uuid,(select channels->>'email'from public.counterparties where id=(p_input->>'professionalId')::uuid),array(select x::uuid from jsonb_array_elements_text(p_input->'verificationEvidenceIds')x),(p_input->>'regulated')::boolean)then raise exception 'needs_approval: verified professional required';end if;
 if(select count(distinct v->>'id')from jsonb_array_elements(p_input->'deliverables')v)<>jsonb_array_length(p_input->'deliverables')then raise exception 'validation: duplicate deliverable';end if;
 for item in select *from jsonb_array_elements(p_input->'deliverables')loop
  if coalesce(item->>'id','')!~'^[A-Za-z0-9_-]{1,80}$'or length(trim(coalesce(item->>'title','')))not between 1 and 200 or jsonb_typeof(item->'requiredFields')is distinct from'array'or jsonb_array_length(item->'requiredFields')not between 1 and 30 or not(quote->'deliverableIds'?(item->>'id'))then raise exception 'validation: quoted deliverables and required fields required';end if;
  for ref in select jsonb_array_elements_text(item->'requiredFields')loop if ref!~'^[A-Za-z][A-Za-z0-9_]{0,79}$'then raise exception 'validation: simple required field names required';end if;end loop;
 end loop;
 if jsonb_array_length(quote->'deliverableIds')<>jsonb_array_length(p_input->'deliverables')then raise exception 'validation: all quoted deliverables must be frozen';end if;
 body:=case when coalesce(p_input->>'language','en')='ar'then 'أنا مساعد يعمل بالذكاء الاصطناعي للمؤسس. وافق المؤسس على التكليف المهني أدناه؛ يؤدي المهني المذكور هذا العمل. يرجى إعادة المستندات والحقول المطلوبة. هذه الرسالة لا توقع أو تقدم أي تسجيل.'else 'I am an AI-assisted agent for the founder. The founder approved the professional engagement below; only the named professional performs this work. Please return the agreed documents and required fields. This message does not sign or file anything.'end||E'\n'||jsonb_build_object('professionalEngagement',p_input,'approvedBrief',brief)::text;
 if length(body)>10000 then raise exception 'validation: professional brief exceeds guarded message size';end if;
 payload:=jsonb_build_object('channel','email','text',body,'translation','I am an AI-assisted agent for the founder. The founder approved the professional engagement below; only the named professional performs this work. Please return the agreed documents and required fields. This message does not sign or file anything.'||E'\n'||jsonb_build_object('professionalEngagement',p_input,'approvedBrief',brief)::text,'language',coalesce(p_input->>'language','en'),'purpose','follow_up','subject','Approved professional engagement brief','hasDocument',false);
 art:=public.create_artifact(p_mission,'professional_engagement',(select a.outcome from public.artifact_versions v join public.artifacts a on a.id=v.artifact_id where v.mission_id=p_mission and v.id=(p_input->>'briefVersionId')::uuid),'Professional engagement: '||(p_input->>'service'));version:=public.append_artifact_version(p_mission,art,jsonb_build_object('professionalEngagement',p_input,'payload',payload));
 for ref in select value from jsonb_array_elements_text(p_input->'verificationEvidenceIds')union select p_input->>'quoteEvidenceId'union select p_input->>'briefVersionId'loop insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,ref::uuid,version,'frozen professional source')on conflict do nothing;end loop;
 insert into public.professional_proposals(mission_id,artifact_version_id)values(p_mission,version);perform public.set_artifact_status(p_mission,version,'proposed');return version;
end$$;

create function public.create_professional_engagement(p_mission uuid,p_decision uuid,p_version uuid,p_mandate uuid,p_key text)returns uuid language plpgsql security definer set search_path=''as $$declare terms jsonb;result uuid;hash text;prior public.professional_engagements;begin
 perform private.require_role(array['specialist_role','lead_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);hash:=encode(public.digest(jsonb_build_object('decision',p_decision,'version',p_version,'mandate',p_mandate)::text,'sha256'),'hex');
 select *into prior from public.professional_engagements where mission_id=p_mission and request_key=p_key;if found then if prior.request_hash<>hash then raise exception 'invariant_violation: professional idempotency mismatch';end if;return prior.id;end if;
 if length(coalesce(p_key,''))not between 16 and 256 then raise exception 'validation: professional request key required';end if;terms:=private.professional_source(p_mission,p_version,true);
 if not exists(select from public.active_decisions d join public.decision_resolutions r on r.mission_id=d.mission_id and r.decision_id=d.id and r.response in('approve','choose')cross join lateral jsonb_array_elements(d.packet->'options')o where d.mission_id=p_mission and d.id=p_decision and d.kind='engagement'and d.gate='professional_engagement'and o->>'id'=r.option_id and o#>'{cost,amountMinor}'=terms->'amountMinor'and o#>>'{cost,currency}'=terms->>'currency'and p_version in(select private.selected_approved_versions(p_mission,p_decision)))then raise exception 'needs_approval: selected Engagement decision with exact professional cost required';end if;
 if p_mandate is not null and not exists(select from public.mandates where mission_id=p_mission and id=p_mandate)then raise exception 'validation: scoped outreach mandate required';end if;
 insert into public.professional_engagements(mission_id,professional_id,decision_id,artifact_version_id,brief_version_id,quote_evidence_id,verification_evidence_ids,email,mandate_id,request_key,request_hash)values(p_mission,(terms->>'professionalId')::uuid,p_decision,p_version,(terms->>'briefVersionId')::uuid,(terms->>'quoteEvidenceId')::uuid,array(select x::uuid from jsonb_array_elements_text(terms->'verificationEvidenceIds')x),(select channels->>'email'from public.counterparties where id=(terms->>'professionalId')::uuid),p_mandate,p_key,hash)returning id into result;return result;
end$$;

create function private.professional_current(p_mission uuid,p_engagement uuid,p_start boolean default false)returns public.professional_engagements language plpgsql stable security definer set search_path=''as $$declare e public.professional_engagements;begin
 select *into strict e from public.professional_engagements where mission_id=p_mission and id=p_engagement;perform private.professional_source(p_mission,e.artifact_version_id,p_start);
 if not exists(select from public.active_decisions where mission_id=p_mission and id=e.decision_id)or not private.professional_verified(p_mission,e.professional_id,e.email,e.verification_evidence_ids,(select(content#>>'{professionalEngagement,regulated}')::boolean from public.artifact_versions where id=e.artifact_version_id))then raise exception 'needs_approval: professional authority or contact changed';end if;return e;
end$$;
create function public.next_professional_engagement(p_mission uuid,p_engagement uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare e public.professional_engagements;draft uuid;begin
 perform private.require_role(array['lead_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);e:=private.professional_current(p_mission,p_engagement,true);if exists(select from public.professional_starts where engagement_id=e.id)then return null;end if;
 select v.id into draft from public.artifact_versions v join public.artifacts a on a.id=v.artifact_id where v.mission_id=p_mission and a.type='outbound_message'and v.content->>'originatingTaskId'=e.task_id::text and v.content->'payload'=(select content->'payload'from public.artifact_versions where id=e.artifact_version_id)and private.readiness_current_approved(p_mission,v.id)order by v.created_at desc,v.id desc limit 1;
 return jsonb_build_object('engagementId',e.id,'taskId',e.task_id,'professionalId',e.professional_id,'artifactVersionId',coalesce(draft,e.artifact_version_id),'mandateId',e.mandate_id);
end$$;
create function private.check_professional_dispatch(p_mission uuid,p_intent jsonb)returns void language plpgsql stable security definer set search_path=''as $$declare e public.professional_engagements;source jsonb;begin
 select *into e from public.professional_engagements where mission_id=p_mission and task_id::text=p_intent->>'taskId';if not found then if exists(select from public.artifact_versions v where v.mission_id=p_mission and v.id::text=p_intent->>'artifactVersionId'and v.content?'professionalEngagement')then raise exception 'needs_approval: professional brief must use its registered approved engagement task';end if;return;end if;e:=private.professional_current(p_mission,e.id,true);
 select content into source from public.artifact_versions where mission_id=p_mission and id::text=p_intent->>'artifactVersionId';
 if p_intent->>'action'is distinct from'send_message'or p_intent->>'channel'is distinct from'email'or p_intent->>'purpose'is distinct from'follow_up'or p_intent->>'counterpartyId'is distinct from e.professional_id::text or source->'payload'is distinct from(select content->'payload'from public.artifact_versions where id=e.artifact_version_id)or(source->>'professionalEngagement'is null and source->>'originatingTaskId'is distinct from e.task_id::text)or exists(select from public.professional_starts where engagement_id=e.id)then raise exception 'needs_approval: professional dispatch identity changed or already started';end if;
end$$;
create function public.record_professional_start(p_mission uuid,p_engagement uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare e public.professional_engagements;result uuid;commitment uuid;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict e from public.professional_engagements where mission_id=p_mission and id=p_engagement;
 select id into result from public.professional_starts where engagement_id=e.id;if found then return result;end if;
 if not exists(select from public.provider_receipts r join public.effect_authorizations a on a.mission_id=r.mission_id and a.id=r.authorization_id join public.messages m on m.mission_id=r.mission_id and m.receipt_id=r.id join public.threads t on t.id=m.thread_id and t.mission_id=m.mission_id join public.artifact_versions v on v.id=e.artifact_version_id where r.mission_id=p_mission and r.id=p_receipt and r.operation='send_message'and r.sandbox_mode=(select sandbox_mode from public.missions where id=p_mission)and a.intent->>'taskId'=e.task_id::text and a.intent->>'counterpartyId'=e.professional_id::text and a.intent->>'channel'='email'and a.intent->>'purpose'='follow_up'and m.direction='outbound'and m.channel='email'and t.counterparty_id=e.professional_id and m.original=v.content#>>'{payload,text}'and exists(select from public.effect_states es where es.authorization_id=a.id and es.status='performed'and es.receipt_id=r.id))then raise exception 'invariant_violation: exact performed professional brief receipt required';end if;
 commitment:=public.open_commitment(p_mission,e.professional_id,'inbound','Professional deliverables for approved engagement '||e.id::text,(select(content#>>'{professionalEngagement,dueAt}')::timestamptz from public.artifact_versions where id=e.artifact_version_id));
 insert into public.professional_starts(mission_id,engagement_id,receipt_id,commitment_id)values(p_mission,e.id,p_receipt,commitment)returning id into result;return result;
end$$;
create function public.reconcile_professional_starts(p_mission uuid)returns integer language plpgsql security definer set search_path=''as $$declare item record;done integer:=0;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform public.reconcile_outbound_receipts(p_mission);
 for item in select e.id,r.id receipt_id from public.professional_engagements e join public.effect_authorizations a on a.mission_id=e.mission_id and a.intent->>'taskId'=e.task_id::text join public.provider_receipts r on r.mission_id=a.mission_id and r.authorization_id=a.id and r.operation='send_message'join public.messages m on m.mission_id=r.mission_id and m.receipt_id=r.id where e.mission_id=p_mission and not exists(select from public.professional_starts where engagement_id=e.id)order by r.created_at,r.id limit 100 loop perform public.record_professional_start(p_mission,item.id,item.receipt_id);done:=done+1;end loop;return done;
end$$;
create function public.hold_professional_engagement(p_mission uuid,p_engagement uuid,p_status text,p_reason text)returns void language plpgsql security definer set search_path=''as $$begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);
 if not exists(select from public.professional_engagements where mission_id=p_mission and id=p_engagement)or coalesce(p_status,'')not in('draft','blocked','ambiguous')or length(coalesce(p_reason,''))not between 1 and 500 then raise exception 'validation: bounded scoped professional hold required';end if;
 if not coalesce((select status=p_status and reason=p_reason from public.professional_holds where engagement_id=p_engagement order by created_at desc,id desc limit 1),false)then insert into public.professional_holds(mission_id,engagement_id,status,reason)values(p_mission,p_engagement,p_status,p_reason);end if;
end$$;

create function private.professional_document(p_mission uuid,p_engagement uuid,p_deliverable text,p_document uuid,p_source uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare e public.professional_engagements;doc jsonb;requirement jsonb;field text;begin
 select *into strict e from public.professional_engagements where mission_id=p_mission and id=p_engagement;
 select item into requirement from public.artifact_versions v cross join lateral jsonb_array_elements(v.content#>'{professionalEngagement,deliverables}')item where v.id=e.artifact_version_id and item->>'id'=p_deliverable;
 select v.content->'professionalDocument'into doc from public.artifact_versions v where v.mission_id=p_mission and v.id=p_document and not exists(select from public.artifact_versions n where n.artifact_id=v.artifact_id and n.version_no>v.version_no)and not exists(select from public.stale_marks s where s.node_id=v.id and s.mission_id=p_mission);
 if requirement is null or doc is null or doc->>'professionalId'is distinct from e.professional_id::text or doc->>'briefVersionId'is distinct from e.brief_version_id::text or doc->>'deliverableId'is distinct from p_deliverable or doc->>'sourceEvidenceId'is distinct from p_source::text or not exists(select from public.evidence evidence where evidence.mission_id=p_mission and evidence.id=p_source and evidence.payload->>'professionalId'=e.professional_id::text and evidence.source_type in('document','message')and private.professional_evidence_current(p_mission,evidence.id))then raise exception 'validation: actual returned source and exact professional deliverable document required';end if;
 for field in select jsonb_array_elements_text(requirement->'requiredFields')loop if not(doc->'fields'?field)or doc#>array['fields',field]='null'::jsonb or length(trim(coalesce(doc#>>array['fields',field],'')))=0 then raise exception 'validation: professional deliverable missing required field %',field;end if;end loop;return doc;
end$$;
create function public.receive_professional_deliverable(p_mission uuid,p_engagement uuid,p_deliverable text,p_document uuid,p_source uuid)returns uuid language plpgsql security definer set search_path=''as $$declare e public.professional_engagements;result uuid;fact uuid;ref uuid;begin
 perform private.require_role(array['specialist_role']);perform private.lock_mission(p_mission);select *into strict e from public.professional_engagements where mission_id=p_mission and id=p_engagement;if not exists(select from public.professional_starts where engagement_id=e.id)then raise exception 'needs_approval: professional work has not started';end if;
 perform private.professional_document(p_mission,e.id,p_deliverable,p_document,p_source);select id into result from public.professional_deliveries where engagement_id=e.id and deliverable_id=p_deliverable and document_version_id=p_document and source_evidence_id=p_source;if found then return result;end if;
 fact:=public.append_evidence(p_mission,null,'professional_deliverable','claimed',jsonb_build_object('engagementId',e.id,'professionalId',e.professional_id,'briefVersionId',e.brief_version_id,'deliverableId',p_deliverable,'documentVersionId',p_document,'sourceEvidenceId',p_source,'requiredFieldsChecked',true),'document','professional-document:'||p_document::text);
 foreach ref in array array[e.artifact_version_id,e.brief_version_id,p_document,p_source]loop insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,ref,fact,'returned professional source')on conflict do nothing;end loop;
 insert into public.professional_deliveries(mission_id,engagement_id,deliverable_id,source_evidence_id,document_version_id,claimed_evidence_id)values(p_mission,e.id,p_deliverable,p_source,p_document,fact)returning id into result;return result;
end$$;
create function public.confirm_professional_deliverable(p_mission uuid,p_decision uuid,p_version uuid)returns uuid language plpgsql security definer set search_path=''as $$declare c jsonb;delivery public.professional_deliveries;e public.professional_engagements;fact uuid;ref text;result uuid;begin
 perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);
 select v.content->'founderConfirmation'into c from public.artifact_versions v join public.active_decisions d on d.mission_id=v.mission_id and d.id=p_decision where v.mission_id=p_mission and v.id=p_version and d.kind='engagement'and d.gate='professional_deliverable_confirmation'and v.id in(select private.selected_approved_versions(p_mission,p_decision))and private.readiness_current_approved(p_mission,v.id);
 if c is null or c->>'kind'is distinct from'professional_deliverable_confirmation'or length(trim(coalesce(c->>'statement','')))=0 or jsonb_typeof(c#>'{payload,sourceEvidenceIds}')is distinct from'array'or jsonb_array_length(c#>'{payload,sourceEvidenceIds}')<1 then raise exception 'needs_approval: explicit selected founder confirmation required';end if;
 select *into strict delivery from public.professional_deliveries where mission_id=p_mission and id=(c#>>'{payload,deliveryId}')::uuid and engagement_id=(c#>>'{payload,engagementId}')::uuid;e:=private.professional_current(p_mission,delivery.engagement_id);perform private.professional_document(p_mission,e.id,delivery.deliverable_id,delivery.document_version_id,delivery.source_evidence_id);
 if not private.professional_evidence_current(p_mission,delivery.claimed_evidence_id)or not(c#>'{payload,sourceEvidenceIds}'?delivery.source_evidence_id::text)then raise exception 'needs_approval: current returned deliverable source must be explicitly confirmed';end if;
 for ref in select jsonb_array_elements_text(c#>'{payload,sourceEvidenceIds}')loop if not private.professional_evidence_current(p_mission,ref::uuid)then raise exception 'validation: current scoped confirmation evidence required';end if;end loop;
 select evidence_id into result from public.professional_confirmations where delivery_id=delivery.id and decision_id=p_decision;if found then return result;end if;
 fact:=public.append_evidence(p_mission,null,'professional_deliverable_verified','founder_confirmed',jsonb_build_object('engagementId',e.id,'deliveryId',delivery.id,'professionalId',e.professional_id,'briefVersionId',e.brief_version_id,'documentVersionId',delivery.document_version_id,'statement',c->>'statement','confirmedAt',clock_timestamp(),'decisionId',p_decision,'artifactVersionId',p_version,'requiredFieldsChecked',true,'agentCertified',false),'document','professional-confirmation:'||p_decision::text||':'||p_version::text);
 for ref in select value from jsonb_array_elements_text(c#>'{payload,sourceEvidenceIds}')union select p_decision::text union select p_version::text union select delivery.claimed_evidence_id::text union select delivery.document_version_id::text loop insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,ref::uuid,fact,'founder verified returned professional source')on conflict do nothing;end loop;
 insert into public.professional_confirmations(mission_id,delivery_id,decision_id,evidence_id)values(p_mission,delivery.id,p_decision,fact);
 if not exists(select from public.artifact_versions v cross join lateral jsonb_array_elements(v.content#>'{professionalEngagement,deliverables}')required where v.id=e.artifact_version_id and not exists(select from public.professional_deliveries d join public.professional_confirmations confirmed on confirmed.delivery_id=d.id where d.engagement_id=e.id and d.deliverable_id=required->>'id'and private.professional_evidence_current(p_mission,confirmed.evidence_id)))then
  insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)select p_mission,confirmed.evidence_id,started.commitment_id,'confirmed professional deliverable closure'from public.professional_deliveries d join public.professional_confirmations confirmed on confirmed.delivery_id=d.id join public.professional_starts started on started.engagement_id=d.engagement_id where d.engagement_id=e.id and private.professional_evidence_current(p_mission,confirmed.evidence_id)on conflict do nothing;
  insert into public.commitment_states(mission_id,commitment_id,status,closed_by_evidence_id)select p_mission,s.commitment_id,'closed',fact from public.professional_starts s where s.engagement_id=e.id and not exists(select from public.commitment_states cs where cs.commitment_id=s.commitment_id and cs.status='closed');end if;return fact;
end$$;

create function private.check_professional_payment(p_mission uuid,p_version uuid)returns void language plpgsql stable security definer set search_path=''as $$declare v jsonb;metadata jsonb;e public.professional_engagements;terms jsonb;begin
 select content into v from public.artifact_versions where mission_id=p_mission and id=p_version;if v#>>'{effectIntent,action}'is distinct from'payment_capture'then return;end if;
 if not(v?'professionalPayment')then if exists(select from public.counterparties c join public.missions m on m.founder_id=c.founder_id where m.id=p_mission and c.id::text=v#>>'{effectIntent,counterpartyId}'and c.kind='specialist')then raise exception 'needs_approval: specialist payment requires exact approved professional engagement';end if;return;end if;
 metadata:=v->'professionalPayment';e:=private.professional_current(p_mission,(metadata->>'engagementId')::uuid);terms:=private.professional_source(p_mission,e.artifact_version_id);
 if metadata->>'artifactVersionId'is distinct from e.artifact_version_id::text or metadata->>'briefVersionId'is distinct from e.brief_version_id::text or v#>>'{effectIntent,counterpartyId}'is distinct from e.professional_id::text or v#>>'{effectIntent,currency}'is distinct from terms->>'currency'or coalesce((v#>>'{effectIntent,amountMinor}')::numeric,0)<=0 or(v#>>'{effectIntent,amountMinor}')::numeric>(terms->>'amountMinor')::numeric then raise exception 'needs_approval: professional payment differs from approved quote';end if;
end$$;
create function private.professional_payment_limit()returns trigger language plpgsql security definer set search_path=''as $$declare metadata jsonb;e public.professional_engagements;used numeric;refunds numeric;ceiling numeric;begin
 if new.intent->>'action'<>'payment_capture'then return new;end if;select content->'professionalPayment'into metadata from public.artifact_versions where mission_id=new.mission_id and id::text=new.intent->>'artifactVersionId';if metadata is null then if exists(select from public.counterparties c join public.missions m on m.founder_id=c.founder_id where m.id=new.mission_id and c.id::text=new.intent->>'counterpartyId'and c.kind='specialist')then raise exception 'needs_approval: actual specialist payment requires professional engagement metadata';end if;return new;end if;
 perform private.check_professional_payment(new.mission_id,(new.intent->>'artifactVersionId')::uuid);e:=private.professional_current(new.mission_id,(metadata->>'engagementId')::uuid);select(content#>>'{professionalEngagement,amountMinor}')::numeric into ceiling from public.artifact_versions where id=e.artifact_version_id;
 if new.intent->>'counterpartyId'is distinct from e.professional_id::text or new.intent->>'currency'is distinct from(select content#>>'{professionalEngagement,currency}'from public.artifact_versions where id=e.artifact_version_id)or coalesce((new.intent->>'amountMinor')::numeric,0)<=0 then raise exception 'needs_approval: actual professional reservation differs from approved payee currency or amount';end if;
 select coalesce(sum((a.intent->>'amountMinor')::numeric),0)into used from public.effect_authorizations a join public.artifact_versions v on v.mission_id=a.mission_id and v.id::text=a.intent->>'artifactVersionId'where a.mission_id=new.mission_id and a.intent->>'action'='payment_capture'and v.content#>>'{professionalPayment,engagementId}'=e.id::text and not exists(select from public.payments p join public.payment_authorizations pa on pa.payment_id=p.id and pa.mission_id=p.mission_id join public.authorization_followups followup on followup.source_authorization_id=pa.id and followup.action='payment_authorization_void'join public.provider_receipts receipt on receipt.authorization_id=followup.effect_authorization_id and receipt.operation='payment_authorization_void'and receipt.mission_id=p.mission_id join public.payment_states state on state.payment_id=p.id and state.mission_id=p.mission_id and state.state='failed'and state.receipt_id=receipt.id where p.authorization_id=a.id and p.mission_id=new.mission_id);
 select coalesce(sum(r.amount_minor),0)into refunds from public.payment_refunds r join public.refund_confirmations confirmed on confirmed.refund_id=r.id join public.payments p on p.id=r.payment_id and p.mission_id=r.mission_id join public.artifact_versions v on v.id=p.artifact_version_id and v.mission_id=p.mission_id where p.mission_id=new.mission_id and v.content#>>'{professionalPayment,engagementId}'=e.id::text;
 if used-refunds+(new.intent->>'amountMinor')::numeric>ceiling then raise exception 'needs_approval: approved professional engagement total exceeded';end if;return new;
end$$;
create trigger professional_payment_limit before insert on public.effect_authorizations for each row execute function private.professional_payment_limit();
create function public.register_professional_payment(p_mission uuid,p_engagement uuid,p_payment uuid)returns uuid language plpgsql security definer set search_path=''as $$declare e public.professional_engagements;p public.payments;metadata jsonb;result uuid;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict e from public.professional_engagements where mission_id=p_mission and id=p_engagement;select *into strict p from public.payments where mission_id=p_mission and id=p_payment;select content->'professionalPayment'into metadata from public.artifact_versions where mission_id=p_mission and id=p.artifact_version_id;
 if metadata->>'engagementId'is distinct from e.id::text or metadata->>'artifactVersionId'is distinct from e.artifact_version_id::text or metadata->>'briefVersionId'is distinct from e.brief_version_id::text or p.payee_id<>e.professional_id or p.sandbox_mode is distinct from(select sandbox_mode from public.missions where id=p_mission)then raise exception 'validation: professional payment lineage differs';end if;
 if not exists(select from public.payment_states s join public.provider_receipts r on r.id=s.receipt_id and r.mission_id=s.mission_id join public.events event on event.id=s.confirmation_event_id and event.mission_id=s.mission_id where s.mission_id=p_mission and s.payment_id=p.id and s.state='captured'and event.signature_verified and r.operation in('payment_capture','payment_authorization_capture'))then raise exception 'invariant_violation: confirmed actual professional payment required';end if;
 select id into result from public.professional_payments where payment_id=p.id;if found then return result;end if;insert into public.professional_payments(mission_id,engagement_id,payment_id)values(p_mission,e.id,p.id)returning id into result;return result;
end$$;

create function public.professional_engagement_snapshot(p_mission uuid,p_engagement uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare e public.professional_engagements;terms jsonb;started public.professional_starts;current boolean:=true;paid numeric;refunded numeric;begin
 perform private.require_role(array['founder_role','lead_role','specialist_role','policy_role']);perform private.assert_mission(p_mission);select *into strict e from public.professional_engagements where mission_id=p_mission and id=p_engagement;
 begin perform private.professional_current(p_mission,e.id);exception when others then current:=false;end;
 select content->'professionalEngagement'into terms from public.artifact_versions where id=e.artifact_version_id;select *into started from public.professional_starts where engagement_id=e.id;
 select coalesce(sum(p.amount_minor),0)into paid from public.professional_payments linked join public.payments p on p.id=linked.payment_id and p.mission_id=linked.mission_id where linked.engagement_id=e.id;
 select coalesce(sum(r.amount_minor),0)into refunded from public.professional_payments linked join public.payment_refunds r on r.payment_id=linked.payment_id and r.mission_id=linked.mission_id where linked.engagement_id=e.id and exists(select from public.refund_confirmations confirmed where confirmed.refund_id=r.id and confirmed.mission_id=r.mission_id);
 return jsonb_build_object('id',e.id,'sandboxMode',(select sandbox_mode from public.missions where id=p_mission),'current',current,'professionalId',e.professional_id,'artifactVersionId',e.artifact_version_id,'briefVersionId',e.brief_version_id,'quoteEvidenceId',e.quote_evidence_id,'started',started.id is not null,'startReceiptId',started.receipt_id,'commitmentId',started.commitment_id,'amountMinor',terms->'amountMinor','currency',terms->>'currency','paidMinor',paid::text,'refundedMinor',refunded::text,'deliveries',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'deliverableId',d.deliverable_id,'documentVersionId',d.document_version_id,'sourceEvidenceId',d.source_evidence_id,'claimedEvidenceId',d.claimed_evidence_id,'confirmed',confirmed.evidence_id is not null,'confirmationEvidenceId',confirmed.evidence_id)order by d.created_at,d.id)from public.professional_deliveries d left join lateral(select c.evidence_id from public.professional_confirmations c where c.delivery_id=d.id and private.professional_evidence_current(p_mission,c.evidence_id)order by c.created_at desc,c.id desc limit 1)confirmed on true where d.engagement_id=e.id),'[]'::jsonb),'paymentIds',coalesce((select jsonb_agg(payment_id order by created_at,id)from public.professional_payments where engagement_id=e.id),'[]'::jsonb));
end$$;
create function private.professional_payment_sources()returns trigger language plpgsql security definer set search_path=''as $$declare e public.professional_engagements;ref uuid;begin
 if not(new.content?'professionalPayment')then return new;end if;
 select *into strict e from public.professional_engagements where mission_id=new.mission_id and id=(new.content#>>'{professionalPayment,engagementId}')::uuid;
 if new.content#>>'{professionalPayment,artifactVersionId}'is distinct from e.artifact_version_id::text or new.content#>>'{professionalPayment,briefVersionId}'is distinct from e.brief_version_id::text then raise exception 'validation: exact professional payment sources required';end if;
 foreach ref in array array[e.artifact_version_id,e.brief_version_id,e.quote_evidence_id,e.decision_id]loop insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(new.mission_id,ref,new.id,'professional payment frozen authority')on conflict do nothing;if exists(select from public.stale_marks s where s.mission_id=new.mission_id and s.node_id=ref)then perform private.invalidate(new.mission_id,new.id,ref);end if;end loop;return new;
end$$;
create trigger professional_payment_sources after insert on public.artifact_versions for each row execute function private.professional_payment_sources();

alter function private.check_version(uuid,uuid)rename to check_version_before_professional;
create function private.check_version(p_mission uuid,p_version uuid)returns void language plpgsql stable security definer set search_path=''as $$begin perform private.check_version_before_professional(p_mission,p_version);perform private.check_professional_payment(p_mission,p_version);end$$;
revoke all on function private.check_version(uuid,uuid)from public;
do $$declare before text;after text;anchor text:='select * into strict v_a from public.effect_authorizations where mission_id=p_mission and id=p_authorization for update;';begin before:=pg_get_functiondef('public.begin_effect(uuid,uuid)'::regprocedure);after:=replace(before,anchor,anchor||' perform private.check_professional_dispatch(p_mission,v_a.intent);');if before=after then raise exception 'migration: professional dispatch anchor changed';end if;execute after;end$$;
do $$declare signature regprocedure;begin for signature in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname like'%professional%'loop execute format('revoke all on function %s from public',signature);end loop;end$$;
revoke all on function public.prepare_professional_engagement(uuid,jsonb),public.create_professional_engagement(uuid,uuid,uuid,uuid,text),public.next_professional_engagement(uuid,uuid),public.record_professional_start(uuid,uuid,uuid),public.reconcile_professional_starts(uuid),public.receive_professional_deliverable(uuid,uuid,text,uuid,uuid),public.confirm_professional_deliverable(uuid,uuid,uuid),public.register_professional_payment(uuid,uuid,uuid)from public;
grant execute on function public.prepare_professional_engagement(uuid,jsonb),public.receive_professional_deliverable(uuid,uuid,text,uuid,uuid)to specialist_role;
grant execute on function public.create_professional_engagement(uuid,uuid,uuid,uuid,text)to specialist_role,lead_role;
grant execute on function public.next_professional_engagement(uuid,uuid)to lead_role;
grant execute on function public.record_professional_start(uuid,uuid,uuid),public.reconcile_professional_starts(uuid),public.register_professional_payment(uuid,uuid,uuid)to policy_role;
revoke all on function public.hold_professional_engagement(uuid,uuid,text,text)from public;grant execute on function public.hold_professional_engagement(uuid,uuid,text,text)to policy_role;
grant execute on function public.confirm_professional_deliverable(uuid,uuid,uuid)to founder_role;
revoke all on function public.professional_engagement_snapshot(uuid,uuid)from public;grant execute on function public.professional_engagement_snapshot(uuid,uuid)to founder_role,lead_role,specialist_role,policy_role;
commit;
